/// <summary>
/// Service to synchronize and log changes in query store query hints.
/// </summary>
public class DBMSQLQueryStoreQueryHintSyncService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Synchronizes current query hints view with previous snapshot, logs changes, and updates snapshot.
/// </summary>
public void process()
{
    DBMSQLQueryStoreQueryHints hintsView;
    DBMSQLQueryStoreQuery queryView;
    DBMSQLQueryStoreQueryHintSnapshot snapshotTable;
    DBMSQLQueryStoreQueryHintLog logTable;

    ttsbegin;

    // 1. Detect and log INSERT changes (hints in hints view, but not in snapshot)
    insert_recordset logTable (QueryHintId, QueryId, NewQueryHintText, QueryHash)
        select QueryHintId, QueryId, QueryHintText from hintsView
            join QueryHash from queryView
            where queryView.QueryId == hintsView.QueryId
            notexists join snapshotTable
            where snapshotTable.QueryHintId == hintsView.QueryHintId;

    // 2. Detect and log UPDATE changes (hints in both, but hint text changed)
    insert_recordset logTable (QueryHintId, QueryId, QueryHash, OldQueryHintText, NewQueryHintText)
        select QueryHintId, QueryId, QueryHash, QueryHintText from snapshotTable
            join QueryHintText from hintsView
            where hintsView.QueryHintId == snapshotTable.QueryHintId
               && hintsView.QueryHintText != snapshotTable.QueryHintText;

    update_recordset logTable
        setting ChangeType = DatabaseLogType::Update
        where logTable.ChangeType == DatabaseLogType::Insert
           && logTable.OldQueryHintText != ''
           && logTable.NewQueryHintText != '';

    // 3. Detect and log DELETE changes (hints in snapshot, but no longer in hints view)
    insert_recordset logTable (QueryHintId, QueryId, QueryHash, OldQueryHintText)
        select QueryHintId, QueryId, QueryHash, QueryHintText from snapshotTable
            notexists join hintsView
            where hintsView.QueryHintId == snapshotTable.QueryHintId;

    update_recordset logTable
        setting ChangeType = DatabaseLogType::Delete
        where logTable.ChangeType == DatabaseLogType::Insert
           && logTable.OldQueryHintText != ''
           && logTable.NewQueryHintText == '';

    // 4. Update snapshot table with current hints
    delete_from snapshotTable;

    insert_recordset snapshotTable (QueryId, QueryHintId, QueryHintText, QueryHash)
        select QueryId, QueryHintId, QueryHintText from hintsView
            join QueryHash from queryView
            where queryView.QueryId == hintsView.QueryId;

    // 5. Clean up log records for query IDs that no longer exist in the main query store table
    delete_from logTable
        notexists join queryView
        where queryView.QueryId == logTable.QueryId;

    ttscommit;
}
